from pathlib import Path
import base64
import subprocess
import zlib

PAYLOAD = """"""

patch = zlib.decompress(base64.b64decode(PAYLOAD))
repo_root = Path(__file__).resolve().parent.parent
for check in (True, False):
    cmd = ["git", "apply"]
    if check:
        cmd.append("--check")
    cmd += ["--whitespace=nowarn", "--directory=a340-app", "-"]
    subprocess.run(cmd, cwd=repo_root, input=patch, check=True)
print("Line Assistant 1.4.5-PC3 possible-cause routing patch applied")
